let targetDevice = "sensor 1";

let rows = msg.payload.filter(r => r.device_id === targetDevice);

// sort by time
rows.sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));

let msgs = [];

rows.forEach(row => {
    msgs.push({
        topic: "Temperature",
        payload: {
            x: new Date(row.timestamp).getTime(),   // <-- IMPORTANT
            y: Number(row.temperature)
        }
    });
});

return msgs;

msg.payload = msg.payload.map(row => {
    return {
        ...row,
        temperature: Number(row.temperature),
        humidity: Number(row.humidity),
        air_quality: Number(row.air_quality),
        battery_level: Number(row.battery_level),
        noise_level: Number(row.noise_level),
        wind_speed: Number(row.wind_speed),
        rain_level_mm: Number(row.rain_level_mm),
        uv_index: Number(row.uv_index),
        cloud_coverage_percent: Number(row.cloud_coverage_percent)
    };
});

return msg;

